import java.io.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.stream.*;


public class E {

    private static final FastReader in = new FastReader();
    private static final FastWriter out = new FastWriter();

    public static void main(String[] args) {
        new E().run();
    }

    private void run() {
        int t = 1;
        while (t-- > 0) {
            solve();
        }
        out.flush();
    }

    private void solve() {
        int n = in.nextInt();
        long k = in.nextLong();

        if (k >= n) {
            out.println(0);
            return;
        }

        final int MOD = 998244353;
        int kInt = (int) k;
        int c = n - kInt;

        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }

        long ans = 0;
        for (int i = 0; i <= c; i++) {
            long comb = fact[c] * modInverse(fact[i] * fact[c - i] % MOD, MOD) % MOD;
            long pow = modPow(c - i, n, MOD);
            long term = comb * pow % MOD;
            if (i % 2 == 0) {
                ans = (ans + term) % MOD;
            } else {
                ans = (ans - term + MOD) % MOD;
            }
        }

        long comb2 = fact[n] * modInverse(fact[n - n + kInt] * fact[n - kInt] % MOD, MOD) % MOD;
        ans = ans * comb2 % MOD;
        if (kInt > 0) {
            ans = ans * 2 % MOD;
        }
        out.println(ans);
    }

    private static long modPow(long a, long b, int mod) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) res = (res * a) % mod;
            a = (a * a) % mod;
            b >>= 1;
        }
        return res;
    }

    private static long modInverse(long a, int mod) {
        return modPow(a, mod - 2, mod);
    }

}


class FastReader {

    private static final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private StringTokenizer st;

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                return null;
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public BigDecimal nextBigDecimal() {
        return new BigDecimal(next());
    }

    public BigInteger nextBigInteger() {
        return new BigInteger(next());
    }

    public boolean nextBoolean() {
        return Boolean.parseBoolean(next());
    }

    public byte nextByte() {
        return Byte.parseByte(next());
    }

    public int[] nextIntArray(int len) {
        int[] a = new int[len];
        for (int i = 0; i < len; i++) a[i] = nextInt();
        return a;
    }

    public long[] nextLongArray(int len) {
        long[] a = new long[len];
        for (int i = 0; i < len; i++) a[i] = nextLong();
        return a;
    }

    public double[] nextDoubleArray(int len) {
        double[] a = new double[len];
        for (int i = 0; i < len; i++) a[i] = nextDouble();
        return a;
    }

}


class FastWriter extends PrintWriter {

    public FastWriter() {
        super(System.out);
    }

    public void println(boolean[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            print(i + 1 < a.length ? ' ' : '\n');
